local _, addon = ...
addon.localeData.deDE.texts = {
    FIREBALL = { name = "Feuerball", ziel = { "Euch wird gleich warm, %s.", "*wirkt Feuerball auf %s.*", "%s, Eure Rüstung ist kein Ersatz für einen Feuerwiderstand." }, gruppe = { "Euch wird gleich warm.", "*konzentriert sich und entfesselt Feuerball.*", "Ein sauberer Feuerball braucht keinen zweiten Versuch.", "*verdichtet eine glühende Kugel zwischen den Handflächen.*", "Die Flamme folgt meiner Hand, nicht meiner Laune.", "*schließt die Finger um einen rotglühenden Feuerkern und schleudert ihn fort.*", "Ein Feuerball ist ein Versprechen aus Glut, das sich nicht zurücknehmen lässt.", "*zupft an glühenden Fäden, bis sie einen eigenen Willen entwickeln.*" } },
    FROSTBOLT = { name = "Frostblitz", ziel = { "Ein frostiger Gruß, %s.", "*wirkt Frostblitz auf %s.*", "%s, jeder Schritt wird Euch jetzt schwerer fallen." }, gruppe = { "Ein frostiger Gruß.", "*konzentriert sich und entfesselt Frostblitz.*", "Der Winter braucht keine Einladung.", "*zieht einen scharfen Eissplitter aus der feuchten Luft.*", "Ein einziger Frostsplitter genügt, um den Übermut zu bremsen.", "*atmet aus, und die Luft zeichnet silberne Kristalllinien.*" } },
    ARCANE_MISSILES = { name = "Arkane Geschosse", ziel = { "Arkane Kräfte finden Euch, %s.", "*wirkt Arkane Geschosse auf %s.*", "%s, fünf Gedanken, ein einziges Ziel." }, gruppe = { "Arkane Kräfte finden Euch.", "*konzentriert sich und entfesselt Arkane Geschosse.*", "Eine Rune für jeden Fehler in Eurer Verteidigung.", "*entlässt mehrere violette Lichtpfeile aus einer schwebenden Glyphe.*", "Die Geschosse finden ihren Weg durch jede Unordnung.", "*teilt einen violetten Lichtfaden in mehrere zielsuchende Funken.*", "Jedes Geschoss folgt einer anderen Rune, und alle treffen denselben Punkt.", "*versetzt eine schwebende Glyphe um Haaresbreite und lauscht dem Summen.*" } },
    FIRE_BLAST = { name = "Feuerschlag", ziel = { "Ein Funke genügt, %s!", "*wirkt Feuerschlag auf %s.*", "%s, dafür brauche ich keinen langen Vortrag." }, gruppe = { "Ein Funke genügt!", "*konzentriert sich und entfesselt Feuerschlag.*", "Ein Augenblick genügt, wenn die Flamme richtig sitzt.", "*schnippt und lässt die Luft mit einem trockenen Knall aufflammen.*", "Ein Fingerschnippen, eine Druckwelle, ein schlechter Tag für die Augenbrauen.", "*zupft an glühenden Fäden, bis sie einen eigenen Willen entwickeln.*" } },
    PYROBLAST = { name = "Pyroschlag", ziel = { "Zeit für ein richtiges Feuerwerk, %s!", "*wirkt Pyroschlag auf %s.*", "%s, diese Formel verdient etwas Abstand." }, gruppe = { "Zeit für ein richtiges Feuerwerk!", "*konzentriert sich und entfesselt Pyroschlag.*", "Dafür brauche ich einen Augenblick. Ihr dafür eine neue Frisur.", "*sammelt mit sichtlicher Mühe eine gewaltige Flamme.*", "Große Flammen erfordern eine ruhige Hand.", "*zieht einen ausgedehnten Feuerkreis und verdichtet ihn zu einer lodernden Kugel.*", "Diese Flamme braucht Zeit zum Wachsen und keinen Platz zum Verstecken.", "*zupft an glühenden Fäden, bis sie einen eigenen Willen entwickeln.*" } },
    FLAMESTRIKE = { name = "Flammenstoß", ziel = { "Der Boden selbst wird brennen!", "*wirkt Flammenstoß auf %s.*", "%s, achtet lieber darauf, wo Ihr steht." }, gruppe = { "Der Boden selbst wird brennen!", "*konzentriert sich und entfesselt Flammenstoß.*", "Der Boden erinnert sich an jedes falsch gesetzte Siegel.", "*zeichnet ein glühendes Muster unter den Füßen der Gegner.*", "Der Boden bekommt ein Siegel, und darüber regnet es Feuer.", "*zupft an glühenden Fäden, bis sie einen eigenen Willen entwickeln.*" } },
    SCORCH = { name = "Versengen", ziel = { "Nur ein kleiner Vorgeschmack, %s.", "*wirkt Versengen auf %s.*", "%s, eine kleine Lektion in angewandter Hitze." }, gruppe = { "Nur ein kleiner Vorgeschmack.", "*konzentriert sich und entfesselt Versengen.*", "Nicht jede Flamme muss ein Inferno werden.", "*streicht zwei Finger durch die Luft und hinterlässt eine schmale Glutspur.*", "Ein schneller Funke ist oft klüger als ein gewaltiger Brand.", "*zupft an glühenden Fäden, bis sie einen eigenen Willen entwickeln.*" } },
    BLIZZARD = { name = "Blizzard", ziel = { "Der Winter kennt keine Gnade!", "*wirkt Blizzard auf %s.*", "%s, sucht Euch besser einen warmen Unterschlupf." }, gruppe = { "Der Winter kennt keine Gnade!", "*konzentriert sich und entfesselt Blizzard.*", "Der Wetterbericht hat sich soeben verschlechtert.", "*ruft ein Wirbeln aus Schnee und scharfkantigem Eis herbei.*", "Wenn der Himmel schweigt, spricht der Schnee.", "*hebt beide Arme und ruft einen Wirbel aus Schnee und scharfem Eis herab.*", "Der Himmel wird weiß, lange bevor der erste Gegner zittert.", "*atmet aus, und die Luft zeichnet silberne Kristalllinien.*" } },
    FROST_NOVA = { name = "Frostnova", ziel = { "Keinen Schritt weiter, %s!", "*wirkt Frostnova auf %s.*", "%s, hier endet Euer Anlauf." }, gruppe = { "Keinen Schritt weiter!", "*konzentriert sich und entfesselt Frostnova.*", "Ihr bleibt genau hier. Die Kälte besteht darauf.", "*lässt eisige Ranken über den Boden kriechen.*", "Die Kälte zeichnet eine Grenze, die niemand übersehen kann.", "*stößt die Handfläche zum Boden und lässt Frost in alle Richtungen springen.*", "Ein Kreis aus Reif erklärt unmissverständlich, wo Ihr stehen bleibt.", "*atmet aus, und die Luft zeichnet silberne Kristalllinien.*" } },
    CONE_OF_COLD = { name = "Kältekegel", ziel = { "Ein Hauch des Nordens!", "*wirkt Kältekegel auf %s.*", "%s, die Winterluft kommt Euch entgegen." }, gruppe = { "Ein Hauch des Nordens!", "*konzentriert sich und entfesselt Kältekegel.*", "Ein Atemzug genügt, um die Nähe ungemütlich zu machen.", "*fächert die Finger auf und treibt einen eisigen Luftkeil vor sich her.*", "Ein kalter Atemzug, breit genug für eine ganze Reihe Unvorsichtiger.", "*atmet aus, und die Luft zeichnet silberne Kristalllinien.*" } },
    ICE_BARRIER = { name = "Eisbarriere", ziel = {  }, gruppe = { "Kälte ist mein Schild.", "*konzentriert sich und entfesselt Eisbarriere.*", "Mein Schutzschild ist aus Geduld und Frost gewoben.", "*legt Schicht um Schicht hauchdünner Eiskristalle um die eigene Gestalt.*", "Jede Eisschicht ist eine weitere Sekunde, die mir gehört.", "*schließt einen glitzernden Schutzkreis mit einer leisen Silbe.*" } },
    ICE_BLOCK = { name = "Eisblock", ziel = {  }, gruppe = { "Ich bin kurz nicht zu sprechen.", "*konzentriert sich und entfesselt Eisblock.*", "Bitte nicht stören. Ich bin gerade tiefgekühlt.", "*schließt sich in kristallklarem Eis ein.*", "Manche Angriffe verdienen keine Antwort, nur eine Pause.", "*schließt die Augen, während klares Eis den Körper umschließt.*", "Manchmal ist die beste Antwort ein vollkommen stiller Augenblick.", "*schließt einen glitzernden Schutzkreis mit einer leisen Silbe.*" } },
    ARCANE_EXPLOSION = { name = "Arkane Explosion", ziel = { "Abstand halten, die Magie wird unruhig!", "*wirkt Arkane Explosion auf %s.*", "%s, tretet aus meinem Zauberkreis." }, gruppe = { "Abstand halten, die Magie wird unruhig!", "*konzentriert sich und entfesselt Arkane Explosion.*", "Abstand ist manchmal die vernünftigste arkanische Disziplin.", "*reißt die Arme auseinander und entlädt einen Ring aus violetter Energie.*", "Die Energie ist längst überall, bevor jemand den Kreis erkennt.", "*versetzt eine schwebende Glyphe um Haaresbreite und lauscht dem Summen.*" } },
    COUNTERSPELL = { name = "Gegenzauber", ziel = { "Eure Worte enden hier, %s!", "*wirkt Gegenzauber auf %s.*", "%s, Eure Silben sind falsch gesetzt." }, gruppe = { "Eure Worte enden hier!", "*konzentriert sich und entfesselt Gegenzauber.*", "Ein schöner Zauber. Schade um die letzte Silbe.", "*zerreißt die fremde Formel mit einer knappen Handbewegung.*", "Ein Zauber kann an einer einzigen gestohlenen Silbe zerbrechen.", "*schneidet mit zwei Fingern eine fremde Formel mitten entzwei.*", "Eine Silbe zu viel, und Eure Formel löst sich in Schweigen auf.", "*versetzt eine schwebende Glyphe um Haaresbreite und lauscht dem Summen.*" } },
    POLYMORPH = { name = "Verwandlung", ziel = { "Ein wenig Wolle steht Euch gut, %s.", "*wirkt Verwandlung auf %s.*", "%s, Ihr habt eben noch deutlich größer gewirkt." }, gruppe = { "Ein wenig Wolle steht Euch gut.", "*konzentriert sich und entfesselt Verwandlung.*", "Ein wenig Wolle würde Euch gut stehen.", "*überlegt kurz, ob Hörner besser wären.*", "Keine Sorge. Das ist meistens reversibel.", "*skizziert die Umrisse eines Schafes.*", "Ich verspreche, die Verwandlung steht Euch ausgezeichnet.", "*mustert sein Gegenüber wie ein Schneider mit sehr viel Fantasie.*", "Ein wenig Demut, vier Hufe und sehr viel Wolle.", "*formt aus Licht die Umrisse eines Schafs und lässt sie über dem Ziel zusammenfallen.*", "Eine andere Gestalt kann den Blick auf die Dinge erheblich verändern.", "*dreht eine Rune und verfolgt die Veränderung der Umrisse.*" } },
    BLINK = { name = "Blinzeln", ziel = {  }, gruppe = { "Einen Augenblick, ich bin gleich woanders.", "*konzentriert sich und entfesselt Blinzeln.*", "Ihr schaut in die falsche Richtung.", "*verschwindet in einem kurzen Flimmern der Luft.*", "Der kürzeste Weg ist nicht immer der sichtbare.", "*verschwindet in einem schmalen blauen Lichtspalt und taucht einen Herzschlag später wieder auf.*", "Der Raum zwischen zwei Schritten ist eine Frage der Übung.", "*dreht die Koordinaten einer schwebenden Karte langsam ins Licht.*" } },
    SLOW_FALL = { name = "Langsamer Fall", ziel = { "Die Schwerkraft kann heute warten.", "*wirkt Langsamer Fall auf %s.*", "Die Schwerkraft wird heute eine Ausnahme machen.", "*zeichnet einen federleichten Bogen unter den Stiefeln von %s.*" }, gruppe = { "Die Schwerkraft kann heute warten.", "*konzentriert sich und entfesselt Langsamer Fall.*", "Die Schwerkraft wird heute eine Ausnahme machen.", "*zeichnet einen federleichten Bogen unter die Stiefel.*", "Die Schwerkraft darf sich heute einen Augenblick gedulden.", "*dreht die Koordinaten einer schwebenden Karte langsam ins Licht.*" } },
    EVOCATION = { name = "Hervorrufung", ziel = {  }, gruppe = { "Einen Moment, ich sammle meine Gedanken und mein Mana.", "*konzentriert sich und entfesselt Hervorrufung.*", "Geduld. Meine Reserven sind nicht unerschöpflich.", "*zieht langsam arkane Ströme aus der Umgebung.*", "Selbst große Kunst braucht gelegentlich eine Atempause.", "*zieht verstreute Manafunken langsam in die Handflächen zurück.*", "Mana kehrt zurück, wenn man die Ströme nicht länger zerstreut.", "*versetzt eine schwebende Glyphe um Haaresbreite und lauscht dem Summen.*" } },
    ARCANE_INTELLECT = { name = "Arkane Intelligenz", ziel = { "Ein klarer Geist ist die beste Waffe, %s.", "*wirkt Arkane Intelligenz auf %s.*", "%s, möge Euer Verstand klarer sein als Euer Schwert." }, gruppe = { "Ein klarer Geist ist die beste Waffe.", "*konzentriert sich und entfesselt Arkane Intelligenz.*", "Ein geschärfter Verstand wiegt mehr als ein ganzer Waffenschrank.", "*setzt eine leuchtende Rune behutsam auf die Stirn.*", "Ein wacher Geist ist der verlässlichste Talisman.", "*setzt eine kleine leuchtende Glyphe an die Schläfe.*", "Ein schärferer Gedanke ist wertvoller als ein schärferes Schwert.", "*legt sanft einen schimmernden Zauberfaden über die ausgestreckte Hand.*" } },
    ARCANE_BRILLIANCE = { name = "Arkane Brillanz", ziel = { "Mögen unsere Gedanken heller leuchten!", "*wirkt Arkane Brillanz auf %s.*", "%s, Wissen wird besser, wenn man es teilt." }, gruppe = { "Mögen unsere Gedanken heller leuchten!", "*konzentriert sich und entfesselt Arkane Brillanz.*", "Die klügste Gruppe ist jene, die gemeinsam denkt.", "*breitet ein Netz heller Runen über die Verbündeten aus.*", "Ein ganzer Kreis wacher Geister ist stärker als einsames Genie.", "*legt sanft einen schimmernden Zauberfaden über die ausgestreckte Hand.*" } },
    MANA_SHIELD = { name = "Manaschild", ziel = {  }, gruppe = { "Mana zu Schutz, Gedanken zu Stahl.", "*konzentriert sich und entfesselt Manaschild.*", "Meine Gedanken sind schwerer zu durchdringen als meine Robe.", "*wickelt fließende Manafäden schützend um die Schultern.*", "Lieber verbrenne ich Mana als meine letzte Robe.", "*schließt einen glitzernden Schutzkreis mit einer leisen Silbe.*" } },
    CONJURE_FOOD = { name = "Essen herbeizaubern", ziel = {  }, gruppe = { "Ein bisschen Magie gegen den Hunger.", "*konzentriert sich und entfesselt Essen herbeizaubern.*", "Ein bisschen Brot hat schon manch heldenhafte Reise gerettet.", "*zaubert mit einer Verbeugung einen kleinen Imbiss hervor.*", "Gute Magie stillt gelegentlich auch den Hunger.", "*öffnet die Hände und lässt einen frisch duftenden Imbiss erscheinen.*", "Die hohe Kunst der Magie sollte auch den Magen überzeugen.", "*verdichtet verstreute Funken zu einer greifbaren Form.*" } },
    CONJURE_WATER = { name = "Wasser herbeizaubern", ziel = {  }, gruppe = { "Frisches Wasser aus reiner Magie.", "*konzentriert sich und entfesselt Wasser herbeizaubern.*", "Wasser ist die vernünftigste aller Beschwörungen.", "*lässt perlende Tropfen zu einer Karaffe verschmelzen.*", "Trinkt. Die arkanen Studien sind ein durstiges Geschäft.", "*fängt einen Tropfen Licht auf und verwandelt ihn in klares Wasser.*", "Ein Tropfen aus dem Nichts, und plötzlich ist die Reise erträglicher.", "*verdichtet verstreute Funken zu einer greifbaren Form.*" } },
    CREATE_MANA_GEM = { name = "Manastein erschaffen", ziel = {  }, gruppe = { "Ein kleiner Vorrat für große Not.", "*konzentriert sich und entfesselt Manastein erschaffen.*", "Eine kleine Reserve für ein großes Problem.", "*presst flackerndes Mana zu einem kühlen, leuchtenden Edelstein.*", "Ein kleiner Kristall, sorgsam mit Reservekraft gefüllt.", "*verdichtet verstreute Funken zu einer greifbaren Form.*" } },
    PORTAL = { name = "Portal", ziel = {  }, gruppe = { "Bitte beim Durchgang keine Gliedmaßen verlieren.", "*konzentriert sich und entfesselt Portal.*", "Wer zuerst hindurchgeht, darf mir anschließend berichten.", "*prüft misstrauisch die Farbe des Portalrandes.*", "Wer hindurchgeht, sollte dem Zielkreis vertrauen.", "*öffnet vorsichtig eine runde Falte im Gewebe des Raumes.*", "Ein Durchgang ist nur dann nützlich, wenn das andere Ende stimmt.", "*dreht die Koordinaten einer schwebenden Karte langsam ins Licht.*" } },
    TELEPORT = { name = "Teleportieren", ziel = {  }, gruppe = { "Ich nehme die Abkürzung durch das Raumgefüge.", "*konzentriert sich und entfesselt Teleportieren.*", "Ein Schritt, ein Koordinatenfehler, tausend Meilen Unterschied.", "*zeichnet die Zielrune und löst sich in einen Wirbel aus Licht auf.*", "Ich falte Entfernung zusammen, statt sie zu durchqueren.", "*dreht die Koordinaten einer schwebenden Karte langsam ins Licht.*" } },
    REMOVE_LESSER_CURSE = { name = "Geringen Fluch aufheben", ziel = { "Der Fluch hat hier nichts verloren, %s.", "*wirkt Geringen Fluch aufheben auf %s.*", "%s, dieser Fluch hat sich lange genug festgekrallt." }, gruppe = { "Der Fluch hat hier nichts verloren.", "*konzentriert sich und entfesselt Geringen Fluch aufheben.*", "Kein Bann hält ewig, wenn man seine Knoten kennt.", "*löst mit einer leuchtenden Rune den Schatten von einer Schulter.*", "Der Fluch hat einen Knoten, und ich kenne seine lose Stelle.", "*legt sanft einen schimmernden Zauberfaden über die ausgestreckte Hand.*" } },
    DETECT_MAGIC = { name = "Magie entdecken", ziel = { "Mal sehen, welche Geheimnisse Ihr tragt, %s.", "*wirkt Magie entdecken auf %s.*", "%s, Eure Aura verrät mehr als Eure Worte." }, gruppe = { "Mal sehen, welche Geheimnisse Ihr tragt.", "*konzentriert sich und entfesselt Magie entdecken.*", "Verborgene Ströme hinterlassen immer eine Spur.", "*hält ein schimmerndes Zeichen ins Licht und betrachtet die Antwort.*", "Unsichtbare Fäden verraten oft mehr als glänzende Rüstungen.", "*versetzt eine schwebende Glyphe um Haaresbreite und lauscht dem Summen.*" } },
    DAMPEN_MAGIC = { name = "Magie dämpfen", ziel = { "Magische Strömungen werden leiser. %s", "%s, ein wenig weniger Zauberlärm wird Euch guttun.", "Nicht jede Macht muss mit voller Stimme sprechen.", "*legt einen silbrigen Schleier über die pulsierenden Manaströme.*" }, gruppe = { "Magische Strömungen werden leiser.", "Nicht jede Macht muss mit voller Stimme sprechen.", "*legt einen silbrigen Schleier über die pulsierenden Manaströme.*", "Ich dämpfe den Fluss, bevor er zu wild wird.", "*legt sanft einen schimmernden Zauberfaden über die ausgestreckte Hand.*" } },
    AMPLIFY_MAGIC = { name = "Magie verstärken", ziel = { "Mehr Magie, mehr Möglichkeiten. %s", "%s, ich öffne Eure Sinne für stärkere Ströme.", "Mehr Kraft ist nur dann ein Geschenk, wenn man sie führen kann.", "*weitet mit einer langsamen Geste den leuchtenden Kreis um den Verbündeten.*" }, gruppe = { "Mehr Magie, mehr Möglichkeiten.", "Mehr Kraft ist nur dann ein Geschenk, wenn man sie führen kann.", "*weitet mit einer langsamen Geste den leuchtenden Kreis um den Verbündeten.*", "Ein wenig mehr Resonanz, aber wehe der Hand, die nicht stillhält.", "*legt sanft einen schimmernden Zauberfaden über die ausgestreckte Hand.*" } },
    FROST_ARMOR = { name = "Frostrüstung", ziel = {  }, gruppe = { "Ein frostiger Mantel steht mir gut.", "Ein kühler Kopf verdient eine ebenso kühle Rüstung.", "*zieht einen schimmernden Reif aus Frost um Schultern und Arme.*", "Ein Mantel aus Kälte kennt keine offenen Nähte.", "*schließt einen glitzernden Schutzkreis mit einer leisen Silbe.*" } },
    ICE_ARMOR = { name = "Eisrüstung", ziel = {  }, gruppe = { "Ein Schutzpanzer aus klirrendem Eis.", "Wer mich berührt, soll zuerst den Winter begrüßen.", "*lässt harte Eisschuppen wie Schuppenpanzer über die Robe wachsen.*", "Das Eis liegt dicht an, leicht wie Stoff und hart wie Stein.", "*schließt einen glitzernden Schutzkreis mit einer leisen Silbe.*" } },
    MAGE_ARMOR = { name = "Magische Rüstung", ziel = {  }, gruppe = { "Mein Geist ist mein bester Panzer.", "Arkane Ordnung beginnt unmittelbar unter meiner Robe.", "*lässt eine kaum sichtbare Schicht schützender Glyphen aufleuchten.*", "Arkane Muster schützen besser, wenn sie sauber ineinandergreifen.", "*schließt einen glitzernden Schutzkreis mit einer leisen Silbe.*" } },
    FIRE_WARD = { name = "Feuerzauberschutz", ziel = {  }, gruppe = { "Feuer soll mich nicht verzehren.", "Feuer erkennt Feuer, aber nicht jedes Feuer darf passieren.", "*schließt einen goldenen Feuerring zu einem schützenden Siegel.*", "Feuer ist willkommen, solange es auf der anderen Seite bleibt.", "*schließt einen glitzernden Schutzkreis mit einer leisen Silbe.*" } },
    FROST_WARD = { name = "Frostzauberschutz", ziel = {  }, gruppe = { "Die Kälte gehorcht mir.", "Der Winter klopft an. Meine Antwort steht bereits fest.", "*spannt einen transparenten Kristallkreis gegen die eisige Luft.*", "Diese Kälte bleibt draußen; ich habe schon genug davon beschworen.", "*schließt einen glitzernden Schutzkreis mit einer leisen Silbe.*" } },
    ARCANE_BLAST = { name = "Arkanbeschuss", ziel = { "Arkane Energie bricht hervor! %s", "%s, diese Energie lässt sich nicht wegdiskutieren.", "Reine Macht braucht keine Flammen, um Spuren zu hinterlassen.", "*stößt eine dichte Welle aus violettem Licht nach vorn.*" }, gruppe = { "Arkane Energie bricht hervor!", "Reine Macht braucht keine Flammen, um Spuren zu hinterlassen.", "*stößt eine dichte Welle aus violettem Licht nach vorn.*", "Ein kurzer Impuls bringt das gesamte Muster ins Wanken.", "*versetzt eine schwebende Glyphe um Haaresbreite und lauscht dem Summen.*" } },
    ARCANE_WRATH = { name = "Arkaner Zorn", ziel = { "Die arkanen Ströme antworten auf meinen Zorn. %s", "%s, meine Geduld war die letzte Schutzschicht.", "Die Arkanen antworten auf Unvernunft mit Nachdruck.", "*verdreht zwei schwebende Siegel, bis ein greller Lichtstoß daraus hervorbricht.*" }, gruppe = { "Die arkanen Ströme antworten auf meinen Zorn.", "Die Arkanen antworten auf Unvernunft mit Nachdruck.", "*verdreht zwei schwebende Siegel, bis ein greller Lichtstoß daraus hervorbricht.*", "Wenn die Runen zürnen, hört selbst das Mana genauer hin.", "*versetzt eine schwebende Glyphe um Haaresbreite und lauscht dem Summen.*" } },
    ARCANE_POWER = { name = "Arkane Macht", ziel = {  }, gruppe = { "Mehr Macht, doch zu welchem Preis?", "Jetzt darf die Theorie zeigen, was sie wirklich wert ist.", "*öffnet die Hände und lässt grelle Runenkreise schneller umeinander rotieren.*", "Für einen Augenblick öffne ich die Schleusen weiter als gewöhnlich.", "*versetzt eine schwebende Glyphe um Haaresbreite und lauscht dem Summen.*" } },
    PRESENCE_OF_MIND = { name = "Geistesgegenwart", ziel = {  }, gruppe = { "Ein Gedanke genügt.", "Manche Gedanken sind schneller als die Zunge.", "*hält kurz inne, als würden alle denkbaren Wege gleichzeitig sichtbar.*", "Der Gedanke ist schon am Ziel, ehe die Hände beginnen.", "*versetzt eine schwebende Glyphe um Haaresbreite und lauscht dem Summen.*" } },
    BLAST_WAVE = { name = "Druckwelle", ziel = { "Ein Sturm aus Feuer und Wucht! %s", "%s, Ihr steht zu nah an meinem Mittelpunkt.", "Wenn die Luft zurückschlägt, ist Abstand keine schlechte Idee.", "*schlägt mit den Handflächen zusammen und treibt eine glühende Druckwelle fort.*" }, gruppe = { "Ein Sturm aus Feuer und Wucht!", "Wenn die Luft zurückschlägt, ist Abstand keine schlechte Idee.", "*schlägt mit den Handflächen zusammen und treibt eine glühende Druckwelle fort.*", "Die Luft selbst wird zur Faust aus Hitze.", "*zupft an glühenden Fäden, bis sie einen eigenen Willen entwickeln.*" } },
    COMBUSTION = { name = "Verbrennung", ziel = {  }, gruppe = { "Die Glut erwacht.", "Jede Glut wird heute bis zum letzten Funken genutzt.", "*zieht die Hitze der Umgebung in eine einzige, flackernde Flamme.*", "Ich hüte die Glut, bis sie alles andere überstrahlt.", "*zupft an glühenden Fäden, bis sie einen eigenen Willen entwickeln.*" } },
    FROSTFIRE_BOLT = { name = "Frostfeuerblitz", ziel = { "Feuer und Eis im selben Atemzug! %s", "%s, entscheidet Euch schnell zwischen Frost und Flammen.", "Ein Widerspruch? Nur für schlechte Magier.", "*verwebt blaue Eissplitter mit roten Feuerfäden zu einem Geschoss.*" }, gruppe = { "Feuer und Eis im selben Atemzug!", "Ein Widerspruch? Nur für schlechte Magier.", "*verwebt blaue Eissplitter mit roten Feuerfäden zu einem Geschoss.*", "Frost und Flamme widersprechen einander nur auf den ersten Blick.", "*zupft an glühenden Fäden, bis sie einen eigenen Willen entwickeln.*" } },
